/// <summary>The commands and events of the <c>CSS</c> domain on a session.</summary>
internal readonly struct CdpCSSDomain(CdpSession session)
{
    /// <summary>Enables the CSS agent for the given page. Clients should not assume that the CSS agent has been enabled until the result of this command is received.</summary>
