        => session.SendAsync("CSS.enable", parameters ?? new(), CdpJsonContext.Default.CSSEnableParams, cancellationToken);

    /// <summary>Returns requested styles for a DOM node identified by `nodeId`.</summary>
    public Task<CSSGetMatchedStylesForNodeResult> GetMatchedStylesForNodeAsync(CSSGetMatchedStylesForNodeParams parameters, CancellationToken cancellationToken = default)
        => session.SendAsync("CSS.getMatchedStylesForNode", parameters ?? new(), CdpJsonContext.Default.CSSGetMatchedStylesForNodeParams, CdpJsonContext.Default.CSSGetMatchedStylesForNodeResult, cancellationToken);

    /// <summary>Calls a handler for each <c>CSS.styleSheetAdded</c> of the session, in the order the browser sent them, until the subscription is disposed.</summary>
    public IDisposable OnStyleSheetAdded(Action<CSSStyleSheetAddedEvent> handler)
        => session.On("CSS.styleSheetAdded", CdpJsonContext.Default.CSSStyleSheetAddedEvent, handler);
